-- Schema for database: rschema_0205

CREATE TABLE `performance_event` (
  `performance_event_id` varchar(255) NOT NULL,
  `name` varchar(255) NOT NULL,
  `time` varchar(255) NOT NULL,
  `location` varchar(255) NOT NULL,
  PRIMARY KEY (`performance_event_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3;

CREATE TABLE `actor` (
  `actor_id` varchar(255) NOT NULL,
  `name` varchar(255) NOT NULL,
  PRIMARY KEY (`actor_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3;

CREATE TABLE `performance_list` (
  `actor_id` varchar(255) NOT NULL,
  `performance_event_id` varchar(255) NOT NULL,
  PRIMARY KEY (`actor_id`, `performance_event_id`),
  CONSTRAINT `performance_list_ibfk_performance_event_id` FOREIGN KEY (`performance_event_id`) REFERENCES `actor` (`performance_event_id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `performance_list_ibfk_actor_id` FOREIGN KEY (`actor_id`) REFERENCES `schema_0` (`actor_id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3;
